sys_script_include.script:
var Session = Class.create();
Session.prototype = {
    TABLE_NAME: "x_776055_workout_session",

    /**
     * @param {GlideRecord|GlideElement|String} record : Used to initialize current record (this.r).
     * 	can be either a gliderecord, a glideElement or a sys_id
     */
    initialize: function(record) {
        if (record && record.getUniqueValue())
            this.r = record;
        else if (record)
            this.r = new GlideRecordUtil().getGR(this.TABLE_NAME, record);
    },

    type: 'Session'
};
